enum E { B = 2 }
console.log(E.A)
console.log(E.B)

namespace N { export const a = 1 }
namespace N { export const b = 2 }
console.log(N.a + N.b)

declare const n: number
try {
  console.log(n)
} catch {
  console.log(0)
}

class A {
  constructor() {
    this.n = 1
    console.log(this.m)
  }
}
class B extends A {
  n = 2
  m = 4
}
const b = new B()
console.log(b.m)
console.log(b.n)

function a(value: unknown, context: unknown) { console.log(1) }
function b(value: unknown, context: unknown) { console.log(2) }
@a
@b
class A {}
console.log(3)

function d(value: unknown, context: { kind: string }) {
  console.log(context.kind)
  return value
}
class A {
  @d
  m() { return 1 }
}
console.log(new A().m())

function d(value: any, context: unknown) {
  return function () { return value.call(this) + 1 }
}
class A {
  @d
  m() { return 1 }
}
console.log(new A().m())

function a(value: unknown, context: unknown) {
  return function () { return 1 }
}
function b(value: unknown, context: unknown) {
  return function () { return 2 }
}
class A {
  @a
  @b
  m() { return 3 }
}
console.log(new A().m())

function dec(value: any, context: unknown) {
  return class extends value {
    n() { return 9 }
  }
}
@dec
class A {
  n() { return 1 }
}
console.log(new A().n())

