class A { n = 1 }
interface A { m: number }
console.log(new A().m)

abstract class A { abstract n(): number }
class B extends A {}
console.log(typeof new B().n)

class A { m() { return 1 } }
class B { m = () => 2 }
console.log(typeof A.prototype.m)
console.log(typeof B.prototype.m)

type Meters = number & { readonly __brand: "m" }
const n = 5 as Meters
console.log(typeof n)

class Meters {
  #brand = 0
  constructor(public n: number) {}
}
console.log(new Meters(4).n)
console.log(Object.keys(new Meters(4)).length)

class A {
  #n = 5
  static read(x: A) { return x.#n }
}
class B extends A {}
console.log(A.read(new B()))

function f(): never { throw new Error("x") }
try {
  f()
} catch {
  console.log(1)
}

type R = { [K in "a" | "b"]: number }
const o: R = { a: 1, b: 2 }
console.log(o.a + o.b)

class A { accessor n = 1 }
const a = new A()
a.n = 2
console.log(a.n)

function f(x: { a: number } | { b: string }) {
  return "a" in x ? x.a : 0
}
console.log(f({ a: 4 }))

